    </section>

    <article class="content-card"><h2>Janelas cadastradas</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Temporada</th><th>Modalidade</th><th>Período</th><th>Limite</th><th>Espera</th><th>Ação</th></tr></thead><tbody><?php foreach (($courseEnrollmentWindows ?? []) as $window) { ?><tr><td><?php echo e($window['temporada_nome']); ?></td><td><?php echo e($window['modalidade_nome'] ?: 'Todas'); ?></td><td><?php echo e($window['data_inicio']); ?> a <?php echo e($window['data_fim']); ?></td><td><?php echo e((string) $window['limite_inscricoes_pessoa']); ?></td><td><?php echo !empty($window['forcar_lista_espera']) ? 'Sim' : 'Não'; ?></td><td><?php if (!empty($window['ativo'])) { ?><form method="POST" action="<?php echo e(url('/admin/temporadas-turmas/inativar')); ?>" data-ajax-form="1" data-follow-redirect="1"><input type="hidden" name="entidade" value="janela"><input type="hidden" name="id" value="<?php echo e((string) $window['id']); ?>"><button type="submit" class="btn btn-secondary">Inativar</button></form><?php } else { ?>Inativa<?php } ?></td></tr><?php } ?></tbody></table></div></article>
