abel><span>Status</span><select name="status"><option value="planejada">Planejada</option><option value="ativa">Ativa</option><option value="suspensa">Suspensa</option><option value="encerrada">Encerrada</option><option value="cancelada">Cancelada</option></select></label><label><span>Limite por CPF</span><input type="number" name="limite_inscricoes_periodo" min="1" value="1"></label></div><label class="checkbox-chip"><input type="checkbox" name="permitir_inscricao_logada" value="1" checked><span>Permitir inscrição logada</span></label><label class="checkbox-chip"><input type="checkbox" name="permitir_inscricao_por_cpf" value="1"><span>Permitir inscrição por CPF</span></label><button type="submit" class="btn btn-primary">Salvar temporada</button></form></div></div></div>
